contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address who) public payable {
        require(who != address(this));
        require(address(c).balance >= 0);

        uint256 beforeBalanceWho = c.balances(who); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalanceWho = c.balances(who); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        assert(!reverted && afterBalanceWho == beforeBalanceWho && afterContractBalance >= beforeContractBalance);
    }

    receive() external payable {}
}

