contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address who) internal {
        vm.assume(who != address(this));
        vm.assume(address(c).balance >= 0);
        uint256 beforeBalanceWho;
        try c.balances(who) returns (uint256 __r) { beforeBalanceWho = __r; } catch { return; }
        uint256 beforeContractBalance = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
